def transform(grid):
    """Mark each present motif at the within-motif coordinate of its tile."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # The solid 3 divider identifies the motif width. Its run is along one
    # axis; on a square board, take the shorter nonzero run of 3-containing
    # rows and columns (a full-width divider spans all columns).
    def longest_run(flags):
        best = cur = 0
        for flag in flags:
            cur = cur + 1 if flag else 0
            best = max(best, cur)
        return best
    row_run = longest_run([any(x == 3 for x in row) for row in out])
    col_run = longest_run([any(out[r][c] == 3 for r in range(h)) for c in range(w)])
    runs = [x for x in (row_run, col_run) if x]
    n = min(runs) if runs else (min(h, w) - 2) // 3
    step = n + 1
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0
    for i, r0 in enumerate(range(0, h, step)):
        for j, c0 in enumerate(range(0, w, step)):
            if any(out[r][c] == 2
                   for r in range(r0, min(r0 + n, h))
                   for c in range(c0, min(c0 + n, w))):
                rr, cc = r0 + i, c0 + j
                if rr < min(r0 + n, h) and cc < min(c0 + n, w) and out[rr][cc] == 2:
                    out[rr][cc] = 8
    return out

