    h, w = len(grid), len(grid[0])
    # The 3-band hides some cells of a macro-grid. Each macro-cell contains
    # a copy of the same small pattern; that pattern is also the occupancy
    # mask for the macro-grid. Its (i,j) pixel determines whether macro-cell
    # (i,j) is present.
    def longest_run(flags):
        best = cur = 0
        for flag in flags:
            cur = cur + 1 if flag else 0
            best = max(best, cur)
        return best
    band_h = longest_run([any(v == 3 for v in row) for row in grid])
    band_w = longest_run([any(grid[r][c] == 3 for r in range(h)) for c in range(w)])
    n = max(band_h, band_w)
    if n == 0:
        n = (min(h, w) - 1) // 4
    step = n + 1

    # Read the prototype from the first nonempty macro-cell outside the band.
    proto = None
    for r0 in range(0, h - n + 1, step):
        for c0 in range(0, w - n + 1, step):
            tile = [[grid[r0 + i][c0 + j] for j in range(n)] for i in range(n)]
            if any(v == 2 for row in tile for v in row):
                proto = tile
                break
        if proto is not None:
            break
    if proto is None:
        return [[0] * w for _ in range(h)]

    out = [[0] * w for _ in range(h)]
    nr = (h + 1) // step
    nc = (w + 1) // step
    for i in range(min(n, nr)):
        for j in range(min(n, nc)):
